insert into public.services
  (id, name, category, status, area, address, location_note, lat, lng, coords, phone, hours, summary, detail, cut_amount, cut_amount_note, effective_date, updated_at, action_label, action_url, alt_categories, source_title, source_url, retrieved, verified)
values
  ('svc-pavement', 'Street pavement maintenance', 'infrastructure', 'reduced', 'citywide', '42551 Osgood Rd, Fremont, CA 94539', 'City of Fremont Maintenance Center', 37.5215, -121.939, 'approximate', '(510) 979-5700', null, 'About $3 million for pavement maintenance and for park and street-median capital replacement was removed from the General Fund to balance the FY 2025/26 budget.', 'The City Manager''s March 30, 2026 letter says the cut "was required to balance the budget" and that waiting to repair infrastructure raises later costs.', 3000000, 'Combined figure for pavement maintenance and park and street-median capital replacement.', '2025-07-01', '2026-03-30', 'Report a street problem to the City', 'https://www.fremont.gov/residents/report-issues', '{}'::text[], 'City Manager letter to Sen. Wahab and Asm. Lee, March 30, 2026', 'https://www.fremont.gov/home/showpublisheddocument/20676/639165034637630000', '2026-10-12', true),
  ('svc-park-median', 'Park and street-median capital replacement', 'parks', 'reduced', 'citywide', '3300 Capitol Ave, Building B, Fremont, CA 94538', 'Parks & Recreation offices, City Hall Building B', 37.5518, -121.9826, 'approximate', '(510) 494-4300', null, 'Capital replacement for parks and street medians was reduced as part of the same roughly $3 million General Fund cut that covered pavement maintenance.', 'The City''s February 13, 2026 release describes it as infrastructure maintenance spending reduced by approximately $3 million to balance the FY 2025/26 budget.', null, 'Included in the roughly $3 million listed under street pavement maintenance; the City does not publish a separate figure.', '2025-07-01', '2026-03-30', 'Report a park or median problem to the City', 'https://www.fremont.gov/residents/report-issues', '{}'::text[], 'City Manager letter to Sen. Wahab and Asm. Lee, March 30, 2026', 'https://www.fremont.gov/home/showpublisheddocument/20676/639165034637630000', '2026-10-12', true),
  ('svc-police-admin', 'Police Department administrative staffing', 'public_safety', 'reduced', '94538', '2000 Stevenson Blvd, Fremont, CA 94538', 'Fremont Police Department', 37.5497, -121.97, 'approximate', '(510) 790-6800', null, 'Six full-time administrative positions in the Police Department were eliminated in the February 10, 2026 budget rebalancing.', 'The City says no reductions were made to current sworn police positions, that positions were eliminated or reclassified, and that no layoffs were anticipated.', null, 'Part of the $3.8 million in operational reductions across all departments.', '2026-02-10', '2026-02-13', null, null, array['Referral']::text[], 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-12', true),
  ('svc-detention', 'Fremont Detention Facility staffing', 'public_safety', 'reduced', '94538', '1990 Stevenson Blvd, Fremont, CA 94538', 'Behind the Police Department building', 37.549, -121.9697, 'approximate', '(510) 790-6800', null, 'Two detention officer positions and one detention supervisor position were eliminated in the February 10, 2026 budget rebalancing.', 'The City says the personnel reductions involve eliminating or reclassifying positions and that no layoffs were anticipated.', null, 'Part of the $3.8 million in operational reductions across all departments.', '2026-02-10', '2026-02-13', null, null, '{}'::text[], 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-12', true),
  ('svc-citywide-ops', 'Department operations: staffing, overtime, training and contract services', 'administration', 'reduced', 'citywide', '3300 Capitol Ave, Fremont, CA 94538', 'Fremont City Hall', 37.5518, -121.9826, 'approximate', '(510) 284-4000', null, 'Every City department reduced spending by its share of $3.8 million in new labor costs ($3.1 million of it in the General Fund). The reductions cover staffing, overtime, training and contract services.', 'The largest reductions were in Police, Fire and Maintenance Operations, which make up most of the General Fund. The City has not published which contract services or programs changed.', 3800000, 'Total for all departments; it includes the police and detention positions listed separately.', '2026-02-10', '2026-02-13', null, null, array['Referral']::text[], 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-12', true),
  ('svc-fire-ops', 'Fire Department operations budget', 'public_safety', 'reduced', 'citywide', '3300 Capitol Ave, Building A, Fremont, CA 94538', 'Fire Administration, City Hall Building A', 37.5518, -121.9826, 'approximate', '(510) 494-4200', null, 'Fire is one of the three departments with the largest reductions in the February 2026 rebalancing. No reductions were made to current sworn fire positions.', 'A March 30, 2026 City letter adds that one more fire company recommended by the department''s Standards of Coverage report is not funded.', null, 'Part of the $3.8 million in operational reductions across all departments.', '2026-02-10', '2026-03-30', null, null, '{}'::text[], 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-12', true),
  ('svc-human-services', 'Human Services safety-net programs', 'human_services', 'reduced', '94538', '3300 Capitol Ave, Building B, Fremont, CA 94538', 'Human Services Department, City Hall Building B', 37.5518, -121.9826, 'approximate', '(510) 574-2050', 'Mon–Fri 8:30 am–5:00 pm; closed 12:00–1:00 pm', 'The City says State and federal funding changes will require eliminating 10 more positions in the Human Services Department, which provides safety-net services.', 'Separately, the FY 2026/27 Proposed Budget shows Human Services staffing going from 82.7 to 79.9 full-time-equivalent positions (a change of 2.8, in funds other than the General Fund). The City has not said which programs are affected.', null, 'The City has not published a dollar figure.', null, '2026-05-12', null, null, array['Food', 'Housing', 'Health', 'Seniors', 'Referral']::text[], 'City Manager letter to Sen. Wahab and Asm. Lee, March 30, 2026', 'https://www.fremont.gov/home/showpublisheddocument/20676/639165034637630000', '2026-10-12', true),
  ('svc-homeless-response', 'Homelessness response services', 'human_services', 'open', 'citywide', '3300 Capitol Ave, Building B, Fremont, CA 94538', 'Human Services Department, City Hall Building B', 37.5518, -121.9826, 'approximate', '(510) 574-2050', null, 'The FY 2025/26 budget kept funding the existing level of homelessness services, about $8 million, and moved $667,000 among programs.', 'That included $150,000 more for Keep Fremont Housed and $128,000 in new funding for overdose prevention and substance use services. This is the status as of the City Manager''s message after the June 10, 2025 adoption; we found no later change in the sources checked.', null, null, '2025-07-01', '2025-06-10', null, null, array['Housing', 'Food', 'Referral']::text[], 'Community Message from the City Manager on the FY 2025/26 Operating Budget', 'https://www.fremont.gov/home/showpublisheddocument/18479/638868997000130000', '2026-10-12', true),
  ('svc-age-well-lake', 'Age Well Center at Lake Elizabeth', 'seniors', 'open', '94538', '40086 Paseo Padre Pkwy, Fremont, CA 94538', null, 37.5451, -121.9665, 'approximate', '(510) 790-6600', 'Mon–Fri 8:00 am–4:30 pm, except City holidays', 'Classes, meals and services for adults 55 and older. Listed as open with regular hours on the City''s Aging and Family Services page.', 'We found no budget-related change for this center in the City sources checked. Call to confirm before visiting.', null, null, null, '2026-10-12', null, null, array['Seniors']::text[], 'Aging and Family Services (City of Fremont)', 'https://www.fremont.gov/residents/older-adults-caregivers', '2026-10-12', true),
  ('svc-age-well-south', 'Age Well Center at South Fremont', 'seniors', 'open', '94539', '47111 Mission Falls Ct, Fremont, CA 94539', null, 37.4897, -121.93, 'approximate', '(510) 742-7540', 'Mon–Fri 8:00 am–4:30 pm, except City holidays', 'Classes, meals and services for adults 55 and older. Listed as open with regular hours on the City''s Aging and Family Services page.', 'We found no budget-related change for this center in the City sources checked. Call to confirm before visiting.', null, null, null, '2026-10-12', null, null, array['Seniors']::text[], 'Aging and Family Services (City of Fremont)', 'https://www.fremont.gov/residents/older-adults-caregivers', '2026-10-12', true),
  ('svc-youth-family', 'Youth and Family Services counseling', 'youth', 'open', '94538', '39155 Liberty St, Suite E500, Fremont, CA 94538', 'Inside the Fremont Family Resource Center', 37.5522, -121.9765, 'approximate', '(510) 574-2100', 'Mon–Fri 8:00 am–5:00 pm', 'Individual and family counseling for Fremont youth and families, with fees on a sliding scale. Listed as open on the City''s Youth and Family Services page.', 'The City lists counseling in Spanish, Farsi, Mandarin, Urdu, Marathi and Hebrew and notes that language capacity can change. We found no budget-related change for this program in the City sources checked.', null, null, null, '2026-10-12', null, null, array['Health', 'Referral']::text[], 'Youth & Family Services (City of Fremont)', 'https://www.fremont.gov/residents/youth', '2026-10-12', true)
insert into public.resources
  (id, name, category, area, address, lat, lng, coords, phone, website, hours, description, languages, language_note, source_url, retrieved, verified)
values
  ('res-tcv', 'TCV Food Bank + Mobile Pantry', 'Food', '94536', '37350 Joseph St, Fremont, CA 94536', 37.5585, -122.0045, 'approximate', '(510) 793-4583', 'https://tcvfoodbank.org/', 'Marketplace: Mon–Thu 10:00 am–2:00 pm; Fri 10:00–11:30 am (drive-thru only)', 'Free groceries for Alameda County residents who meet income requirements. First-time shoppers bring an ID to sign up for a TCV card; new cards are not issued on Fridays. Mobile pantry sites are listed on the website.', '{}'::text[], 'Website available in English, Spanish, Chinese, Farsi and Vietnamese.', 'https://tcvfoodbank.org/', '2026-10-12', true),
  ('res-211', '211 Alameda County', 'Referral', 'citywide', 'Phone and online service', null, null, null, '211', 'https://211alamedacounty.org/', '24 hours a day, 7 days a week', 'Free, confidential help from a person who can refer you to food, housing, health and other services in Alameda County.', '{}'::text[], 'Ask about language help when you call.', 'https://211alamedacounty.org/', '2026-10-12', true),
  ('res-frc', 'Fremont Family Resource Center', 'Referral', '94538', '39155 Liberty St, Fremont, CA 94538', 37.5522, -121.9765, 'approximate', '(510) 574-2000', 'https://www.fremont.gov/government/departments/human-services', null, 'A City-run center that houses City, County and nonprofit agencies in one place. Call to ask which agency can help and whether it takes walk-ins.', '{}'::text[], null, 'https://www.fremont.gov/about/department-directory', '2026-10-12', true),
  ('res-senior-infoline', 'City of Fremont Senior InfoLine', 'Seniors', 'citywide', '3300 Capitol Ave, Building B, Fremont, CA 94538', 37.5518, -121.9826, 'approximate', '(510) 574-2041', 'https://www.fremont.gov/residents/older-adults-caregivers', 'Office Mon–Fri 8:30 am–5:00 pm; closed 12:00–1:00 pm', 'Resources and help for older adults and caregivers, including benefits questions. Leave a message and the City says calls are returned within 2 days.', array['English', 'Spanish', 'Farsi', 'Mandarin']::text[], null, 'https://www.fremont.gov/residents/older-adults-caregivers', '2026-10-12', true),
  ('res-bach-liberty', 'Bay Area Community Health: Liberty Clinic', 'Health', '94538', '39500 Liberty St, Fremont, CA 94538', 37.5489, -121.9759, 'approximate', '(510) 770-8040', 'https://bach.health/alameda-county-locations', 'Mon–Thu 8:00 am–7:00 pm; Fri–Sat 8:00 am–5:00 pm', 'Community health center with medical, behavioral health and vision care, plus help with health insurance. The phone number is the appointment line for all Bay Area Community Health clinics.', '{}'::text[], null, 'https://bach.health/alameda-county-locations', '2026-10-12', true),
  ('res-bach-irvington', 'Bay Area Community Health: Irvington Dave Clinic', 'Health', '94538', '40910 Fremont Blvd, Fremont, CA 94538', 37.5325, -121.9605, 'approximate', '(510) 770-8040', 'https://bach.health/alameda-county-locations', 'Medical: Mon–Fri 8:00 am–7:00 pm, Sun 8:00 am–5:00 pm. Dental: Mon–Fri 8:00 am–7:00 pm, Sat 8:00 am–5:00 pm', 'Medical, pediatric, behavioral health and dental care, plus help with health insurance. Call the appointment line first.', '{}'::text[], null, 'https://bach.health/alameda-county-locations', '2026-10-12', true),
  ('res-bach-mowry', 'Bay Area Community Health: Mowry II Clinic', 'Health', '94538', '1999 Mowry Ave, Fremont, CA 94538', 37.5573, -121.9773, 'approximate', '(510) 770-8040', 'https://bach.health/alameda-county-locations', 'Medical: Mon–Fri 8:00 am–5:00 pm. Teen Clinic: Mon–Thu 9:00 am–6:00 pm, Fri 8:00 am–5:00 pm. Convenient Care: Mon–Fri 5:00–8:00 pm', 'Medical and behavioral health care with a Teen Clinic and Women''s Health. Several suites share this address; ask which one when you call.', '{}'::text[], null, 'https://bach.health/alameda-county-locations', '2026-10-12', true),
  ('res-988', '988 Suicide & Crisis Lifeline', 'Crisis', 'citywide', 'Phone service', null, null, null, '988', 'https://988lifeline.org/', '24 hours a day, 7 days a week', 'Trained crisis counselors by phone at any hour. The City''s Youth and Family Services page points residents to this line. For a life-threatening emergency call 911.', '{}'::text[], null, 'https://www.fremont.gov/residents/youth', '2026-10-12', true),
  ('res-abode', 'Abode Services', 'Housing', '94538', '40849 Fremont Blvd, Fremont, CA 94538', 37.5333, -121.9612, 'approximate', '(510) 657-7409', 'https://abode.org/', null, 'Nonprofit that provides housing and support services for people experiencing homelessness. This is the administrative office; call to ask how to get help.', '{}'::text[], null, 'https://abode.org/', '2026-10-12', true),
  ('res-iiba', 'Immigration Institute of the Bay Area: Fremont', 'Legal', '94538', '39055 Hastings St, Suite 202, Fremont, CA 94538', 37.5535, -121.979, 'approximate', '(510) 894-3639', 'https://iibayarea.org/offices/fremont/', null, 'Nonprofit immigration legal services and workshops for Alameda County. First consultations are booked by phone or online.', '{}'::text[], 'The website and booking instructions are also in Spanish.', 'https://iibayarea.org/offices/fremont/', '2026-10-12', true),
  ('res-lov', 'League of Volunteers (LOV)', 'Community', 'citywide', 'PO Box 1170, Newark, CA 94560 (no walk-in office)', null, null, null, '(510) 793-5683', 'https://www.lov.org/contact-lov', 'Tue–Fri 9:00 am–2:00 pm', 'Tri-City nonprofit that runs holiday food and toy drives, Adopt-A-Family, summer recreation and community events. The staff work remotely, so call or email first.', '{}'::text[], null, 'https://www.lov.org/contact-lov', '2026-10-12', true),
  ('res-library-fremont', 'Fremont Library', 'Library', '94538', '2400 Stevenson Blvd, Fremont, CA 94538', 37.5512, -121.9745, 'approximate', '(510) 745-1400', 'https://aclibrary.org/locations/', null, 'Alameda County Library branch. It is run by the County, not paid for from the City of Fremont budget. Hours differ by day; check the website or call.', '{}'::text[], null, 'https://aclibrary.org/locations/', '2026-10-12', true),
  ('res-library-centerville', 'Centerville Library', 'Library', '94536', '3801 Nicolet Ave, Fremont, CA 94536', 37.5603, -122.0105, 'approximate', '(510) 795-2629', 'https://aclibrary.org/locations/', null, 'Alameda County Library branch. It is run by the County, not paid for from the City of Fremont budget. Hours differ by day; check the website or call.', '{}'::text[], null, 'https://aclibrary.org/locations/', '2026-10-12', true),
  ('res-library-niles', 'Niles Library', 'Library', '94536', '150 I St, Fremont, CA 94536', 37.5773, -121.9806, 'approximate', '(510) 795-2626', 'https://aclibrary.org/locations/', null, 'Alameda County Library branch. It is run by the County, not paid for from the City of Fremont budget. Hours differ by day; check the website or call.', '{}'::text[], null, 'https://aclibrary.org/locations/', '2026-10-12', true)
insert into public.alerts
  (id, title, body, category, area, severity, published_at, service_id, source_title, source_url, retrieved, verified)
values
  ('alert-election-2026', 'Council Districts 2, 3 and 4 are on the November 3, 2026 ballot', 'Fremont holds its General Municipal Election on November 3, 2026. Voters in Districts 2, 3 and 4 choose their councilmembers. The City''s election page lists the candidates and a tool to find your district.', 'civic', 'citywide', 'info', '2026-08-07', null, 'Election Information (City of Fremont)', 'https://www.fremont.gov/government/election-information', '2026-10-12', true),
  ('alert-tax-deferred', 'Council defers a possible half-cent sales tax measure', 'News reports say the Council voted unanimously to defer a half-cent sales tax measure instead of placing it on the November 2026 ballot. City staff are expected to return with other ways to close the funding gap.', 'budget', 'citywide', 'info', '2026-07-24', null, 'Hoodline, July 24, 2026', 'https://hoodline.com/2026/07/fremont-council-slams-brakes-on-half-cent-tax-hike-before-november-vote-6944803/', '2026-10-12', true),
  ('alert-budget-2627', 'FY 2026/27 budget adopted with no room to restore earlier cuts', 'The Council adopted the FY 2026/27 Operating Budget on June 9, 2026. The proposed budget kept staffing and services at current-year levels, including the FY 2025/26 reductions, and said there was no capacity to restore eliminated positions or services.', 'budget', 'citywide', 'warning', '2026-06-12', 'svc-citywide-ops', 'FY 2026/27 Proposed Budget presentation, May 12, 2026 (City of Fremont)', 'https://www.fremont.gov/home/showpublisheddocument/20494/639142770931900000', '2026-10-12', true),
  ('alert-human-services', 'City says 10 more Human Services positions will be eliminated', 'A March 30, 2026 letter from the City Manager says State and federal funding changes will require eliminating 10 more positions in the Human Services Department, which provides safety-net services. The City has not said which programs are affected.', 'human_services', 'citywide', 'warning', '2026-03-30', 'svc-human-services', 'City Manager letter to Sen. Wahab and Asm. Lee, March 30, 2026', 'https://www.fremont.gov/home/showpublisheddocument/20676/639165034637630000', '2026-10-12', true),
  ('alert-rebalance', 'Budget rebalancing approved: reductions in every department', 'On February 10, 2026 the Council approved reductions in staffing, overtime, training and contract services to cover $3.8 million in new labor costs. The Police Department eliminated six administrative positions, two detention officers and one detention supervisor. No sworn police or fire positions were cut.', 'public_safety', 'citywide', 'warning', '2026-02-13', 'svc-police-admin', 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-12', true),
  ('alert-maintenance', 'About $3 million less for streets, parks and medians', 'To balance the FY 2025/26 budget adopted on June 10, 2025, the City reduced infrastructure maintenance spending by about $3 million. A later City letter describes this as pavement maintenance and park and street-median capital replacement.', 'infrastructure', 'citywide', 'warning', '2025-06-10', 'svc-pavement', 'City Council Approves Budget Rebalancing (City of Fremont, Feb 13, 2026)', 'https://www.fremont.gov/Home/Components/News/News/1665/1067', '2026-10-12', true)
insert into public.posts
  (id, body, area, upvotes, status, is_sample, created_at)
values
  ('post-sample-1', 'Starter tip: TCV Food Bank''s Marketplace is open Monday to Thursday 10 am to 2 pm, and Friday is drive-thru only from 10 to 11:30 am. First-time shoppers need an ID.', '94536', 0, 'approved', true, '2026-10-12T16:00:00Z'),
  ('post-sample-2', 'Starter tip: Dial 211 at any hour for free referrals to food, housing and health services in Alameda County.', 'citywide', 0, 'approved', true, '2026-10-12T16:00:00Z'),
  ('post-sample-3', 'Starter tip: The City''s Senior InfoLine is 510-574-2041. You can leave a message in English, Spanish, Farsi or Mandarin.', 'citywide', 0, 'approved', true, '2026-10-12T16:00:00Z')
